	/**
	 * Default Constructor
	 */
    public SimCardService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new SimCardEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(SimCardRepository.class) );
		this.validator		= applicationContext.getBean(SimCardValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		SimCard
	 */
		public SimCard createSimCard( CreateSimCardCommand command ) {

		SimCard entity = new SimCard();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setSimCardId( command.getSimCardId() );
            entity.setIccid( command.getIccid() );
            entity.setImsi( command.getImsi() );
            entity.setCarrier( command.getCarrier() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of SimCard {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateSimCardCommand
	 * @return		SimCard
	 */
	public SimCard updateSimCard( UpdateSimCardCommand command ) {

		SimCard entity = new SimCard();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setSimCardId( command.getSimCardId() );
            entity.setIccid( command.getIccid() );
            entity.setImsi( command.getImsi() );
            entity.setCarrier( command.getCarrier() );
            entity.setNetworkProfiles( command.getNetworkProfiles() );
            entity.setTenant( command.getTenant() );
            entity.setConnectivityPlan( command.getConnectivityPlan() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of SimCard {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteSimCardCommand
	 */
	public void delete( DeleteSimCardCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getSimCardId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of SimCard {0} ", id );

	}

	/**
	 * Method to retrieve the SimCard via SimCardFetchOneSummary
	 * @param 	summary SimCardFetchOneSummary
	 * @return 	SimCardFetchOneResponse
	 */
	public SimCard getSimCard( SimCardFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "SimCardFetchOneSummary arg cannot be null" );

		SimCard entity = null;
		UUID id = summary.getSimCardId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a SimCard using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all SimCards
	 *
	 * @return 	List<SimCard>
	 */
    public List<SimCard> getAllSimCard() {
		List<SimCard> list = projector.findAll( new FindAllSimCardQuery() );
		return list;
	}

	/**
	 * assign Tenant on SimCard
	 * @param		command AssignTenantToSimCardCommand
	 */
	public void assignTenant( AssignTenantToSimCardCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignTenant(command.getSimCardId(), command.getAssignment());

	}

	/**
	 * unAssign Tenant on SimCard
	 * @param		command UnAssignTenantFromSimCardCommand
	 */
	public void unAssignTenant( UnAssignTenantFromSimCardCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignTenant(command.getSimCardId());
	}
	
